    const [a, b] = [...pointers.current.values()];
    const m = toMap((a.x + b.x) / 2, (a.y + b.y) / 2), v = viewRef.current;
    pinch.current = { dist: Math.hypot(a.x - b.x, a.y - b.y) || 1, wx: (m.x - v.tx) / v.k, wy: (m.y - v.ty) / v.k, k: v.k };
