    if (pz && pointers.current.size >= 2) {
      const [a, b] = [...pointers.current.values()];
      const m = toMap((a.x + b.x) / 2, (a.y + b.y) / 2);
      const k = Math.max(MIN_K, Math.min(MAX_K, (pz.k * Math.hypot(a.x - b.x, a.y - b.y)) / pz.dist));
